#include<bits/stdc++.h>
using namespace std;
#define int long long
#define PII pair<int, int>
#define xx first
#define yy second
const int N = 1e6 + 10;
int ww[N], n, m, fa[N], mi, dep[N], ans[N], f[N], re[N];
struct node{int u, v, w, id;};
vector<node> e, g;
vector<PII> G[N];
bool fl[N];
int find(int x){
	if(fa[x] != x)fa[x] = find(fa[x]);
	return fa[x];
}
void dfs(int x, int fa){
	f[x] = fa;
	dep[x] = dep[fa] + 1;
	for(auto i : G[x]){
		if(i.xx == fa)continue;
		re[i.yy] = i.xx; 
		dfs(i.xx, x);
	}
}
signed main(){
	ios::sync_with_stdio(0);
	cin.tie(0), cout.tie(0);
	cin >> n >> m;
	for(int i = 1; i <= n; i ++)fa[i] = i;
	for(int i = 1; i <= m; i ++){
		int u, v, w;
		cin >> u >> v >> w;
		ww[i] = w;
		e.push_back({u, v, w, i});
	}
	sort(e.begin(), e.end(), [](auto a, auto b){
		return a.w < b.w;
	});
	for(int i = 0; i < m; i ++){
		int x = find(e[i].u), y = find(e[i].v);
		if(x == y){
			g.push_back(e[i]);
			continue;
		}
		fl[e[i].id] = 1;
		G[e[i].u].push_back({e[i].v, e[i].id});
		G[e[i].v].push_back({e[i].u, e[i].id}); 
		mi += e[i].w; 
		fa[x] = y;
	}
	for(int i = 2; i <= n; i ++){
		if(find(i) != find(1)){
			for(int j = 1; j <= m; j ++)cout << -1 << '\n'; 
			return 0;
		}
	}
	dfs(1, 0);
	for(int i = 1; i <= n; i ++)ans[i] = -1, fa[i] = i;
	for(auto i : g){
		int u = find(i.u), v = find(i.v), w = i.w;
		while(u != v){
			if(dep[u] < dep[v])swap(u, v); 
			ans[u] = w; 
			fa[u] = find(f[u]); 
			u = find(u); 
		}
